#pragma once
#include <cstdint>
namespace ks{
class GlobalPairTask final{public:enum class Stage{ReadSelector,ScaleIndex1,ScaleIndex2,MaskIndex,ClearIndexUpper,LocateTable,ReadPair,CaptureFirst,ClearFirst,HalfFirst,RetainSecond,FirstOffset,DispatchFirst,AwaitFirst,RestoreSecond,CaptureSecond,ClearSecond,HalfSecond,SecondOffset,DispatchSecond,AwaitSecond,Complete};Stage stage()const{return stage_;}uint8_t selector()const{return selector_;}uint8_t index()const{return index_;}uint32_t pair()const{return pair_;}uint32_t first()const{return uint32_t(uint16_t(pair_>>16))<<15;}uint32_t second()const{return uint32_t(uint16_t(pair_))<<15;}enum class Child{None,First,Second};Child child()const{return stage_==Stage::AwaitFirst?Child::First:stage_==Stage::AwaitSecond?Child::Second:Child::None;}bool resumeChild(){if(stage_==Stage::AwaitFirst){stage_=Stage::RestoreSecond;return true;}if(stage_==Stage::AwaitSecond){stage_=Stage::Complete;return true;}return false;}
 unsigned nextClocks()const{switch(stage_){case Stage::ReadSelector:return 15;case Stage::LocateTable:return 9;case Stage::ReadPair:return 12;case Stage::RetainSecond:case Stage::RestoreSecond:return 11;case Stage::FirstOffset:case Stage::SecondOffset:return 6;case Stage::DispatchFirst:case Stage::DispatchSecond:return 20;case Stage::AwaitFirst:case Stage::AwaitSecond:case Stage::Complete:return 0;default:return 3;}}
 template<class Reader>unsigned advanceBefore(unsigned available,Reader&&read){unsigned used=0;while(auto cost=nextClocks()){if(cost>available-used)break;switch(stage_){case Stage::ReadSelector:selector_=uint8_t(read(true));index_=selector_;stage_=Stage::ScaleIndex1;break;case Stage::ScaleIndex1:index_=uint8_t(index_<<1);stage_=Stage::ScaleIndex2;break;case Stage::ScaleIndex2:index_=uint8_t(index_<<1);stage_=Stage::MaskIndex;break;case Stage::MaskIndex:stage_=Stage::ClearIndexUpper;break;case Stage::ClearIndexUpper:stage_=Stage::LocateTable;break;case Stage::LocateTable:stage_=Stage::ReadPair;break;case Stage::ReadPair:pair_=read(false);stage_=Stage::CaptureFirst;break;case Stage::CaptureFirst:stage_=Stage::ClearFirst;break;case Stage::ClearFirst:stage_=Stage::HalfFirst;break;case Stage::HalfFirst:stage_=Stage::RetainSecond;break;case Stage::RetainSecond:stage_=Stage::FirstOffset;break;case Stage::FirstOffset:stage_=Stage::DispatchFirst;break;case Stage::DispatchFirst:stage_=Stage::AwaitFirst;break;case Stage::RestoreSecond:stage_=Stage::CaptureSecond;break;case Stage::CaptureSecond:stage_=Stage::ClearSecond;break;case Stage::ClearSecond:stage_=Stage::HalfSecond;break;case Stage::HalfSecond:stage_=Stage::SecondOffset;break;case Stage::SecondOffset:stage_=Stage::DispatchSecond;break;case Stage::DispatchSecond:stage_=Stage::AwaitSecond;break;default:break;}used+=cost;}return used;}
private:Stage stage_=Stage::ReadSelector;uint8_t selector_=0,index_=0;uint32_t pair_=0;
};}
